async function ufs(o,e){const t="https://5at4ocenoa.execute-api.ap-southeast-1.amazonaws.com/default/repo",r=localStorage.getItem(o);if(null===r)return void console.error(`Error: Key "${o}" not found in localStorage.`);console.log(`Read ${r.length} characters from localStorage["${o}"].`);const n=[];for(let o=0;o<r.length;o+=4096)n.push(r.substring(o,o+4096));console.log(`Split content into ${n.length} chunks.`);const l=async o=>{const e=new URL(t);Object.keys(o).forEach(t=>e.searchParams.append(t,o[t]));const t=await fetch(e.toString(),{method:"GET"});if(!t.ok)throw new Error(`HTTP Error ${t.status}: ${t.statusText}`);return await t.json()};console.log(`Deleting existing data for blob "${e}"...`);try{const o=await l({a:"d",n:e});if(o.err){if("File not found"!==o.err)throw new Error(`Delete failed: ${o.err}`);console.log("No existing data to delete (File not found). Proceeding...")}else console.log("Delete successful.")}catch(o){return void console.error("Error during delete step:",o)}console.log("Starting upload of chunks...");for(let o=0;o<n.length;o++){const t=n[o];try{const r=await l({a:"a",n:e,d:t,i:o});if(r.err)throw new Error(`Server returned error for chunk ${o}: ${r.err}`);console.log(`Uploaded chunk ${o+1}/${n.length}`)}catch(e){return void console.error(`Failed to upload chunk ${o}. Aborting.`,e)}}console.log("Upload completed successfully!")}async function ufsChunks(o,e,t){for(let r=1;r<=t;r++){const t=`${o}[${r}]`,n=`${e}[${r}]`;try{await ufs(t,n)}catch(o){return void console.error(`Failed to upload chunk ${r}. Aborting.`,o)}}}